:root {
  --font-sans: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Hiragino Sans", "Hiragino Kaku Gothic ProN", "Yu Gothic", "Meiryo", sans-serif;

  /* Primary & Accent Colors */
  --color-primary: #3b82f6;
  --color-primary-hover: #2563eb;
  --color-primary-light: #eff6ff;
  --color-primary-text: #1d4ed8;

  /* Priority Colors */
  --priority-high-bg: #fee2e2;
  --priority-high-text: #dc2626;
  --priority-high-border: #fca5a5;

  --priority-medium-bg: #fef3c7;
  --priority-medium-text: #d97706;
  --priority-medium-border: #fcd34d;

  --priority-low-bg: #e0f2fe;
  --priority-low-text: #0284c7;
  --priority-low-border: #7dd3fc;

  /* Neutrals & Surfaces */
  --bg-app: #f1f5f9;
  --bg-column: #e2e8f0;
  --bg-card: #ffffff;
  --bg-input: #ffffff;
  --border-subtle: #cbd5e1;
  --border-focus: #3b82f6;

  /* Text Colors */
  --text-main: #0f172a;
  --text-muted: #64748b;
  --text-inverse: #ffffff;

  /* Danger / Warning */
  --color-danger: #ef4444;
  --color-danger-hover: #dc2626;
  --color-danger-bg: #fef2f2;

  /* Shadows */
  --shadow-sm: 0 1px 2px 0 rgba(0, 0, 0, 0.05);
  --shadow-md: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -2px rgba(0, 0, 0, 0.08);
  --shadow-lg: 0 10px 15px -3px rgba(0, 0, 0, 0.1), 0 4px 6px -4px rgba(0, 0, 0, 0.08);
  --shadow-card: 0 1px 3px 0 rgba(15, 23, 42, 0.08), 0 1px 2px -1px rgba(15, 23, 42, 0.04);
  --shadow-card-hover: 0 8px 16px -2px rgba(15, 23, 42, 0.12), 0 4px 6px -2px rgba(15, 23, 42, 0.06);

  /* Radius */
  --radius-sm: 6px;
  --radius-md: 10px;
  --radius-lg: 14px;
  --radius-full: 9999px;
}

*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html, body {
  height: 100%;
  font-family: var(--font-sans);
  background-color: var(--bg-app);
  color: var(--text-main);
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
}

#root {
  min-height: 100vh;
  display: flex;
  flex-direction: column;
}

/* メインアプリケーションコンテナ */
.kanban-app {
  display: flex;
  flex-direction: column;
  min-height: 100vh;
  padding: 24px;
  max-width: 1440px;
  margin: 0 auto;
  width: 100%;
}

/* ヘッダーエリア */
.app-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 16px;
  margin-bottom: 20px;
}

.header-title {
  font-size: 1.75rem;
  font-weight: 800;
  color: #0f172a;
  letter-spacing: -0.02em;
  display: flex;
  align-items: center;
  gap: 10px;
}

.header-stats {
  display: flex;
  align-items: center;
  gap: 10px;
}

.stat-badge {
  background-color: #ffffff;
  padding: 6px 14px;
  border-radius: var(--radius-full);
  font-size: 0.85rem;
  font-weight: 600;
  color: var(--text-muted);
  box-shadow: var(--shadow-sm);
  border: 1px solid var(--border-subtle);
  display: inline-flex;
  align-items: center;
  gap: 6px;
}

/* ツールバー（検索・絞り込み・新規作成） */
.app-toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 24px;
  flex-wrap: wrap;
  background-color: #ffffff;
  padding: 12px 16px;
  border-radius: var(--radius-md);
  box-shadow: var(--shadow-sm);
  border: 1px solid #e2e8f0;
}

.search-input {
  flex: 1;
  min-width: 200px;
  max-width: 380px;
  padding: 10px 14px;
  font-size: 0.925rem;
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-sm);
  background-color: var(--bg-input);
  color: var(--text-main);
  outline: none;
  transition: border-color 0.15s ease, box-shadow 0.15s ease;
}

.search-input:focus {
  border-color: var(--border-focus);
  box-shadow: 0 0 0 3px rgba(59, 130, 246, 0.2);
}

.priority-filter-select {
  padding: 10px 14px;
  font-size: 0.925rem;
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-sm);
  background-color: var(--bg-input);
  color: var(--text-main);
  outline: none;
  cursor: pointer;
  transition: border-color 0.15s ease, box-shadow 0.15s ease;
}

.priority-filter-select:focus {
  border-color: var(--border-focus);
  box-shadow: 0 0 0 3px rgba(59, 130, 246, 0.2);
}

.add-task-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 10px 18px;
  font-size: 0.925rem;
  font-weight: 600;
  border-radius: var(--radius-sm);
  background-color: var(--color-primary);
  color: var(--text-inverse);
  border: none;
  cursor: pointer;
  transition: background-color 0.15s ease, transform 0.1s ease;
  white-space: nowrap;
}

.add-task-btn:hover {
  background-color: var(--color-primary-hover);
}

.add-task-btn:active {
  transform: translateY(1px);
}

/* カンバンボード領域 */
.kanban-board {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 20px;
  flex: 1;
  align-items: flex-start;
}

/* 各カラム */
.kanban-column {
  background-color: var(--bg-column);
  border-radius: var(--radius-lg);
  padding: 16px;
  display: flex;
  flex-direction: column;
  min-height: 480px;
  transition: background-color 0.2s ease, border-color 0.2s ease, box-shadow 0.2s ease;
  border: 2px dashed transparent;
}

.kanban-column-over {
  background-color: #cbd5e1;
  border-color: var(--color-primary);
  box-shadow: 0 0 0 3px rgba(59, 130, 246, 0.25);
}

.column-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 14px;
  padding-bottom: 10px;
  border-bottom: 2px solid rgba(0, 0, 0, 0.05);
}

.column-title-wrap {
  display: flex;
  align-items: center;
  gap: 8px;
}

.column-title {
  font-size: 1.05rem;
  font-weight: 700;
  color: #1e293b;
}

.task-count-pill {
  background-color: rgba(0, 0, 0, 0.08);
  font-size: 0.8rem;
  font-weight: 700;
  padding: 2px 8px;
  border-radius: var(--radius-full);
  color: var(--text-muted);
}

.column-add-btn {
  background: transparent;
  border: none;
  font-size: 1.25rem;
  line-height: 1;
  width: 28px;
  height: 28px;
  border-radius: var(--radius-sm);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  color: var(--text-muted);
  cursor: pointer;
  transition: background-color 0.15s ease, color 0.15s ease;
}

.column-add-btn:hover {
  background-color: rgba(0, 0, 0, 0.08);
  color: var(--text-main);
}

.task-list {
  display: flex;
  flex-direction: column;
  gap: 12px;
  flex: 1;
  min-height: 200px;
}

.empty-column-msg {
  display: flex;
  align-items: center;
  justify-content: center;
  height: 120px;
  border: 1px dashed var(--border-subtle);
  border-radius: var(--radius-md);
  color: var(--text-muted);
  font-size: 0.875rem;
  text-align: center;
  padding: 16px;
  user-select: none;
}

/* タスクカード */
.task-card {
  background-color: var(--bg-card);
  border-radius: var(--radius-md);
  padding: 14px;
  box-shadow: var(--shadow-card);
  cursor: grab;
  user-select: none;
  display: flex;
  flex-direction: column;
  gap: 10px;
  border: 1px solid #e2e8f0;
  transition: transform 0.15s ease, box-shadow 0.15s ease, opacity 0.15s ease;
  position: relative;
}

.task-card:hover {
  transform: translateY(-2px);
  box-shadow: var(--shadow-card-hover);
}

.task-card:active {
  cursor: grabbing;
}

.task-card-dragging {
  opacity: 0.4;
  border: 2px dashed var(--color-primary);
  box-shadow: none;
}

.card-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}

.card-priority {
  font-size: 0.725rem;
  font-weight: 700;
  padding: 3px 8px;
  border-radius: var(--radius-full);
  display: inline-flex;
  align-items: center;
  gap: 4px;
  text-transform: uppercase;
}

.card-priority-high {
  background-color: var(--priority-high-bg);
  color: var(--priority-high-text);
  border: 1px solid var(--priority-high-border);
}

.card-priority-medium {
  background-color: var(--priority-medium-bg);
  color: var(--priority-medium-text);
  border: 1px solid var(--priority-medium-border);
}

.card-priority-low {
  background-color: var(--priority-low-bg);
  color: var(--priority-low-text);
  border: 1px solid var(--priority-low-border);
}

.card-title {
  font-size: 0.975rem;
  font-weight: 600;
  color: #0f172a;
  line-height: 1.4;
  word-break: break-word;
}

.card-desc {
  font-size: 0.85rem;
  color: #475569;
  line-height: 1.5;
  white-space: pre-wrap;
  word-break: break-word;
}

.card-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-top: 8px;
  border-top: 1px solid #f1f5f9;
  font-size: 0.8rem;
  color: var(--text-muted);
  gap: 8px;
}

.card-due-date {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  font-size: 0.775rem;
  color: #64748b;
}

.card-actions {
  display: flex;
  align-items: center;
  gap: 4px;
  margin-left: auto;
}

.move-btn {
  background-color: #f1f5f9;
  border: 1px solid #e2e8f0;
  border-radius: 4px;
  padding: 3px 6px;
  font-size: 0.75rem;
  color: #475569;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  line-height: 1;
  transition: background-color 0.15s ease, color 0.15s ease;
}

.move-btn:hover {
  background-color: #e2e8f0;
  color: #0f172a;
}

.card-icon-btn {
  background: transparent;
  border: none;
  cursor: pointer;
  color: #94a3b8;
  padding: 4px;
  border-radius: 4px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  transition: color 0.15s ease, background-color 0.15s ease;
}

.card-icon-btn:hover {
  color: #334155;
  background-color: #f1f5f9;
}

.card-icon-btn.btn-danger:hover {
  color: var(--color-danger);
  background-color: var(--color-danger-bg);
}

/* ボタン汎用スタイル */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  padding: 8px 16px;
  font-size: 0.9rem;
  font-weight: 600;
  border-radius: var(--radius-sm);
  border: none;
  cursor: pointer;
  transition: background-color 0.15s ease, transform 0.1s ease;
}

.btn:active {
  transform: translateY(1px);
}

.btn-primary {
  background-color: var(--color-primary);
  color: var(--text-inverse);
}

.btn-primary:hover {
  background-color: var(--color-primary-hover);
}

.btn-secondary {
  background-color: #e2e8f0;
  color: #334155;
}

.btn-secondary:hover {
  background-color: #cbd5e1;
}

.btn-danger {
  background-color: var(--color-danger);
  color: var(--text-inverse);
}

.btn-danger:hover {
  background-color: var(--color-danger-hover);
}

/* モーダル */
.modal-backdrop {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background-color: rgba(15, 23, 42, 0.55);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 1000;
  padding: 16px;
  backdrop-filter: blur(2px);
}

.modal-content {
  background-color: #ffffff;
  border-radius: var(--radius-lg);
  width: 100%;
  max-width: 520px;
  box-shadow: var(--shadow-lg);
  display: flex;
  flex-direction: column;
  overflow: hidden;
  animation: modalIn 0.2s cubic-bezier(0.16, 1, 0.3, 1);
}

@keyframes modalIn {
  from {
    opacity: 0;
    transform: scale(0.96) translateY(8px);
  }
  to {
    opacity: 1;
    transform: scale(1) translateY(0);
  }
}

.modal-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 18px 22px;
  border-bottom: 1px solid #f1f5f9;
}

.modal-title {
  font-size: 1.15rem;
  font-weight: 700;
  color: #0f172a;
}

.modal-close-btn {
  background: transparent;
  border: none;
  font-size: 1.25rem;
  color: var(--text-muted);
  cursor: pointer;
  padding: 4px;
  line-height: 1;
  border-radius: 4px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  transition: color 0.15s ease, background-color 0.15s ease;
}

.modal-close-btn:hover {
  color: var(--text-main);
  background-color: #f1f5f9;
}

.modal-form {
  padding: 22px;
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.form-group {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.form-label {
  font-size: 0.85rem;
  font-weight: 600;
  color: #334155;
}

.form-input,
.form-select,
.form-textarea {
  width: 100%;
  padding: 9px 12px;
  font-size: 0.9rem;
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-sm);
  background-color: var(--bg-input);
  color: var(--text-main);
  outline: none;
  font-family: inherit;
  transition: border-color 0.15s ease, box-shadow 0.15s ease;
}

.form-input:focus,
.form-select:focus,
.form-textarea:focus {
  border-color: var(--border-focus);
  box-shadow: 0 0 0 3px rgba(59, 130, 246, 0.2);
}

.form-textarea {
  min-height: 90px;
  resize: vertical;
}

.form-row {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 14px;
}

.modal-footer {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 10px;
  padding: 16px 22px;
  border-top: 1px solid #f1f5f9;
  background-color: #f8fafc;
}

/* レスポンシブ対応 */
@media (max-width: 900px) {
  .kanban-board {
    grid-template-columns: 1fr;
    gap: 16px;
  }

  .kanban-column {
    min-height: 280px;
  }

  .app-toolbar {
    flex-direction: column;
    align-items: stretch;
  }

  .search-input {
    max-width: 100%;
  }

  .form-row {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 480px) {
  .kanban-app {
    padding: 14px;
  }

  .header-title {
    font-size: 1.4rem;
  }

  .header-stats {
    width: 100%;
    justify-content: flex-start;
  }
}

import type { DragEvent } from 'react';

/**
 * カンバンボードのカラム（タスク状態）
 */
export type TaskStatus = 'todo' | 'in_progress' | 'done';

/**
 * タスクの優先度
 */
export type TaskPriority = 'low' | 'medium' | 'high';

/**
 * タスクアイテムの完全な型定義
 */
export interface TaskItem {
  id: string;
  title: string;
  description: string;
  status: TaskStatus;
  priority: TaskPriority;
  dueDate: string;
  createdAt: string;
}

/**
 * タスク作成・更新用フォームデータ（ID・作成日を除く）
 */
export type TaskFormData = Omit<TaskItem, 'id' | 'createdAt'>;

/**
 * タスク保存処理における判別可能なユニオン型
 */
export type TaskSaveAction =
  | { mode: 'create'; taskData: TaskFormData; editId?: never }
  | { mode: 'edit'; taskData: TaskFormData; editId: string };

/**
 * タスク保存ハンドラーの型定義
 * 作成時（引数1つまたは第2引数がundefined）と編集時（editId指定）の両方に型安全に対応
 */
export interface TaskSaveHandler {
  (taskData: TaskFormData, editId?: string): void;
  (taskData: TaskFormData): void;
  (taskData: TaskFormData, editId: string): void;
}

/**
 * タスク編集・作成モーダルのProps
 */
export interface TaskModalProps {
  isOpen: boolean;
  taskToEdit: TaskItem | null;
  initialStatus: TaskStatus;
  onClose: () => void;
  onSave: TaskSaveHandler;
}

/**
 * カンバンカラムコンポーネントのProps
 */
export interface KanbanColumnProps {
  status: TaskStatus;
  title: string;
  tasks?: TaskItem[];
  onDragStart?: (e: DragEvent<HTMLDivElement>, id: string) => void;
  onDragOver?: (e: DragEvent<HTMLDivElement>) => void;
  onDragLeave?: (e: DragEvent<HTMLDivElement>) => void;
  onDrop?: (e: DragEvent<HTMLDivElement>, status: TaskStatus) => void;
  onOpenAddModal?: (status: TaskStatus) => void;
  onOpenEditModal?: (task: TaskItem) => void;
  onDeleteTask?: (id: string) => void;
  onMoveTask?: (id: string, newStatus: TaskStatus) => void;
}

/**
 * タスクカードコンポーネントのProps
 */
export interface TaskCardProps {
  task: TaskItem;
  onDragStart?: (e: DragEvent<HTMLDivElement>, id: string) => void;
  onOpenEditModal?: (task: TaskItem) => void;
  onDeleteTask?: (id: string) => void;
  onMoveTask?: (id: string, newStatus: TaskStatus) => void;
}

import { useState, type DragEvent } from 'react';
import { Calendar, Edit3, Trash2, ArrowLeft, ArrowRight, AlertCircle } from 'lucide-react';
import type { TaskCardProps, TaskPriority } from '../types';

const priorityLabels: Record<TaskPriority, string> = {
  high: '高',
  medium: '中',
  low: '低',
};

const priorityClasses: Record<TaskPriority, string> = {
  high: 'card-priority-high',
  medium: 'card-priority-medium',
  low: 'card-priority-low',
};

const getLocalDateString = (): string => {
  const now = new Date();
  const year = now.getFullYear();
  const month = String(now.getMonth() + 1).padStart(2, '0');
  const day = String(now.getDate()).padStart(2, '0');
  return `${year}-${month}-${day}`;
};

const TaskCard = ({
  task,
  onDragStart,
  onOpenEditModal,
  onDeleteTask,
  onMoveTask,
}: TaskCardProps) => {
  const [isDragging, setIsDragging] = useState<boolean>(false);

  const handleDragStart = (e: DragEvent<HTMLDivElement>) => {
    setIsDragging(true);
    e.dataTransfer.effectAllowed = 'move';
    e.dataTransfer.setData('text/plain', task.id);
    onDragStart(e, task.id);
  };

  const handleDragEnd = () => {
    setIsDragging(false);
  };

  const handlePreviousStatus = () => {
    if (task.status === 'done') {
      onMoveTask(task.id, 'in_progress');
    } else if (task.status === 'in_progress') {
      onMoveTask(task.id, 'todo');
    }
  };

  const handleNextStatus = () => {
    if (task.status === 'todo') {
      onMoveTask(task.id, 'in_progress');
    } else if (task.status === 'in_progress') {
      onMoveTask(task.id, 'done');
    }
  };

  const todayStr = getLocalDateString();
  const isOverdue = task.status !== 'done' && Boolean(task.dueDate) && task.dueDate < todayStr;
  const cardClassName = `task-card ${isDragging ? 'task-card-dragging' : ''}`;

  return (
    <div
      className={cardClassName}
      draggable
      onDragStart={handleDragStart}
      onDragEnd={handleDragEnd}
    >
      <div className="card-header">
        <span className={`card-priority ${priorityClasses[task.priority]}`}>
          {priorityLabels[task.priority]}
        </span>
        <div className="card-actions">
          <button
            type="button"
            className="card-icon-btn"
            title="編集"
            onClick={() => onOpenEditModal(task)}
          >
            <Edit3 size={15} />
          </button>
          <button
            type="button"
            className="card-icon-btn btn-danger"
            title="削除"
            onClick={() => onDeleteTask(task.id)}
          >
            <Trash2 size={15} />
          </button>
        </div>
      </div>

      <h4 className="card-title">{task.title}</h4>

      {task.description && (
        <p className="card-desc">{task.description}</p>
      )}

      <div className="card-footer">
        <div
          className="card-due-date"
          style={isOverdue ? { color: 'var(--color-danger)', fontWeight: 600 } : undefined}
          title={isOverdue ? '期限が過ぎています' : undefined}
        >
          {isOverdue ? <AlertCircle size={13} /> : <Calendar size={13} />}
          <span>{task.dueDate ? (isOverdue ? `${task.dueDate} (期限切)` : task.dueDate) : '期日なし'}</span>
        </div>

        <div className="card-actions">
          {task.status !== 'todo' && (
            <button
              type="button"
              className="move-btn"
              title="前のステータスへ移動"
              onClick={handlePreviousStatus}
            >
              <ArrowLeft size={13} />
            </button>
          )}
          {task.status !== 'done' && (
            <button
              type="button"
              className="move-btn"
              title="次のステータスへ移動"
              onClick={handleNextStatus}
            >
              <ArrowRight size={13} />
            </button>
          )}
        </div>
