import { useState, type DragEvent } from 'react';
import { Plus } from 'lucide-react';
import type { KanbanColumnProps } from '../types';
import TaskCard from './TaskCard';

const KanbanColumn = ({
  status,
  title,
  tasks = [],
  onDragStart,
  onDragOver,
  onDragLeave,
  onDrop,
  onOpenAddModal,
  onOpenEditModal,
  onDeleteTask,
  onMoveTask,
}: KanbanColumnProps) => {
  const [isOver, setIsOver] = useState<boolean>(false);

  const handleDragOver = (e: DragEvent<HTMLDivElement>) => {
    e.preventDefault();
    setIsOver(true);
    onDragOver?.(e);
  };

  const handleDragLeave = (e: DragEvent<HTMLDivElement>) => {
    e.preventDefault();
    if (e.currentTarget.contains(e.relatedTarget as Node)) {
      return;
    }
    setIsOver(false);
    onDragLeave?.(e);
  };

  const handleDrop = (e: DragEvent<HTMLDivElement>) => {
    e.preventDefault();
    setIsOver(false);
    onDrop?.(e, status);
  };

  const columnClassName = `kanban-column ${isOver ? 'kanban-column-over' : ''}`;

  return (
    <div
      className={columnClassName}
      onDragOver={handleDragOver}
      onDragLeave={handleDragLeave}
      onDrop={handleDrop}
    >
      <div className="column-header">
        <div className="column-title-wrap">
          <h3 className="column-title">{title}</h3>
          <span className="task-count-pill">{tasks.length}</span>
        </div>
        <button
          type="button"
          className="column-add-btn"
          title={`${title}にタスクを追加`}
          onClick={() => onOpenAddModal?.(status)}
        >
          <Plus size={16} />
        </button>
      </div>

      <div className="task-list">
        {tasks.length === 0 ? (
          <div className="empty-column-msg">タスクがありません</div>
        ) : (
          tasks.map((task) => (
            <TaskCard
              key={task.id}
              task={task}
              onDragStart={onDragStart}
              onOpenEditModal={onOpenEditModal}
              onDeleteTask={onDeleteTask}
              onMoveTask={onMoveTask}
            />
          ))
        )}
      </div>
    </div>
  );
};

export default KanbanColumn;

import { useState, useEffect, useRef, type FormEvent } from 'react';
import { X } from 'lucide-react';
import type { TaskModalProps, TaskPriority, TaskStatus } from '../types';

const getLocalDateString = (): string => {
  const now = new Date();
  const year = now.getFullYear();
  const month = String(now.getMonth() + 1).padStart(2, '0');
  const day = String(now.getDate()).padStart(2, '0');
  return `${year}-${month}-${day}`;
};

const TaskModal = ({
  isOpen,
  taskToEdit,
  initialStatus,
  onClose,
  onSave,
}: TaskModalProps) => {
  const [title, setTitle] = useState<string>('');
  const [description, setDescription] = useState<string>('');
  const [status, setStatus] = useState<TaskStatus>(initialStatus);
  const [priority, setPriority] = useState<TaskPriority>('medium');
  const [dueDate, setDueDate] = useState<string>('');

  const modalRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (taskToEdit) {
      setTitle(taskToEdit.title);
      setDescription(taskToEdit.description);
      setStatus(taskToEdit.status);
      setPriority(taskToEdit.priority);
      setDueDate(taskToEdit.dueDate);
    } else {
      setTitle('');
      setDescription('');
      setStatus(initialStatus);
      setPriority('medium');
      setDueDate(getLocalDateString());
    }
  }, [taskToEdit, initialStatus, isOpen]);

  useEffect(() => {
    if (!isOpen) return;

    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'Escape') {
        onClose();
        return;
      }

      if (e.key === 'Tab') {
        if (!modalRef.current) return;
        const focusableElements = modalRef.current.querySelectorAll<HTMLElement>(
          'button, [href], input, select, textarea, [tabindex]:not([tabindex="-1"])'
        );
        if (focusableElements.length === 0) return;

        const firstElement = focusableElements[0];
        const lastElement = focusableElements[focusableElements.length - 1];

        if (e.shiftKey) {
          if (document.activeElement === firstElement) {
            e.preventDefault();
            lastElement.focus();
          }
        } else {
          if (document.activeElement === lastElement) {
            e.preventDefault();
            firstElement.focus();
          }
        }
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => {
      window.removeEventListener('keydown', handleKeyDown);
    };
  }, [isOpen, onClose]);

  if (!isOpen) {
    return null;
  }

  const handleSubmit = (e: FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    if (!title.trim()) {
      return;
    }

    onSave(
      {
        title: title.trim(),
        description: description.trim(),
        status,
        priority,
        dueDate,
      },
      taskToEdit?.id
    );
    onClose();
  };

  return (
    <div className="modal-backdrop" onClick={onClose}>
      <div
        ref={modalRef}
        className="modal-content"
        role="dialog"
        aria-modal="true"
        aria-labelledby="modal-title"
        onClick={(e) => e.stopPropagation()}
      >
        <div className="modal-header">
          <h3 id="modal-title" className="modal-title">
            {taskToEdit ? 'タスクを編集' : '新規タスク作成'}
          </h3>
          <button
            type="button"
            className="modal-close-btn"
            onClick={onClose}
            aria-label="閉じる"
          >
            <X size={20} />
          </button>
        </div>

        <form onSubmit={handleSubmit} className="modal-form">
          <div className="form-group">
            <label className="form-label" htmlFor="task-title">
              タイトル <span style={{ color: 'var(--color-danger)' }}>*</span>
            </label>
            <input
              id="task-title"
              type="text"
              className="form-input"
              value={title}
              onChange={(e) => setTitle(e.target.value)}
              placeholder="例: 会議資料の作成"
              required
              autoFocus
            />
          </div>

          <div className="form-group">
            <label className="form-label" htmlFor="task-desc">
              説明・メモ
            </label>
            <textarea
              id="task-desc"
              className="form-textarea"
              value={description}
              onChange={(e) => setDescription(e.target.value)}
              placeholder="詳細内容やチェック項目を入力..."
            />
          </div>

          <div className="form-row">
            <div className="form-group">
              <label className="form-label" htmlFor="task-status">
                ステータス
              </label>
              <select
                id="task-status"
                className="form-select"
                value={status}
                onChange={(e) => setStatus(e.target.value as TaskStatus)}
              >
                <option value="todo">未着手</option>
                <option value="in_progress">作業中</option>
                <option value="done">完了</option>
              </select>
            </div>

            <div className="form-group">
              <label className="form-label" htmlFor="task-priority">
                優先度
              </label>
              <select
                id="task-priority"
                className="form-select"
                value={priority}
                onChange={(e) => setPriority(e.target.value as TaskPriority)}
              >
                <option value="low">低</option>
                <option value="medium">中</option>
                <option value="high">高</option>
              </select>
            </div>
          </div>

          <div className="form-group">
            <label className="form-label" htmlFor="task-due-date">
              期限日
            </label>
            <input
              id="task-due-date"
              type="date"
              className="form-input"
              value={dueDate}
              onChange={(e) => setDueDate(e.target.value)}
            />
          </div>

          <div className="modal-footer">
            <button
              type="button"
              className="btn btn-secondary"
              onClick={onClose}
            >
              キャンセル
            </button>
            <button type="submit" className="btn btn-primary">
              {taskToEdit ? '変更を保存' : 'タスクを追加'}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
};

