  { status: 'todo', title: '未着手' },
  { status: 'in_progress', title: '作業中' },
  { status: 'done', title: '完了' },
];

const generateUniqueId = (): string => {
  if (typeof crypto !== 'undefined' && typeof crypto.randomUUID === 'function') {
    return crypto.randomUUID();
  }
  return `task-${Date.now()}-${Math.random().toString(36).slice(2, 9)}`;
};

const getLocalDateString = (): string => {
  const now = new Date();
  const year = now.getFullYear();
  const month = String(now.getMonth() + 1).padStart(2, '0');
  const day = String(now.getDate()).padStart(2, '0');
  return `${year}-${month}-${day}`;
};

const loadInitialTasks = (): TaskItem[] => {
  try {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved) {
      const parsed = JSON.parse(saved);
      if (Array.isArray(parsed) && parsed.length > 0) {
        return parsed;
      }
    }
  } catch (err) {
    console.error('Failed to load tasks from localStorage:', err);
  }
  return defaultTasks;
};

const App = () => {
  const [tasks, setTasks] = useState<TaskItem[]>(loadInitialTasks);
  const [searchQuery, setSearchQuery] = useState<string>('');
  const [priorityFilter, setPriorityFilter] = useState<TaskPriority | 'all'>('all');
  const [draggedTaskId, setDraggedTaskId] = useState<string | null>(null);

  // モーダル管理
  const [isModalOpen, setIsModalOpen] = useState<boolean>(false);
  const [taskToEdit, setTaskToEdit] = useState<TaskItem | null>(null);
  const [modalInitialStatus, setModalInitialStatus] = useState<TaskStatus>('todo');

  useEffect(() => {
    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(tasks));
    } catch (err) {
      console.error('Failed to save tasks to localStorage:', err);
    }
  }, [tasks]);

  // ドラッグ処理
  const handleDragStart = (_e: DragEvent<HTMLDivElement>, id: string) => {
    setDraggedTaskId(id);
  };

  const handleDragOver = (e: DragEvent<HTMLDivElement>) => {
    e.preventDefault();
  };

  const handleDrop = (e: DragEvent<HTMLDivElement>, targetStatus: TaskStatus) => {
    e.preventDefault();
    if (!draggedTaskId) return;

    setTasks((prevTasks) =>
      prevTasks.map((task) =>
        task.id === draggedTaskId ? { ...task, status: targetStatus } : task
      )
    );
    setDraggedTaskId(null);
  };

  // タスク操作ロジック
  const handleMoveTask = (id: string, newStatus: TaskStatus) => {
    setTasks((prevTasks) =>
      prevTasks.map((task) =>
        task.id === id ? { ...task, status: newStatus } : task
      )
    );
  };

  const handleDeleteTask = (id: string) => {
    setTasks((prevTasks) => prevTasks.filter((task) => task.id !== id));
  };

  const handleOpenAddModal = (status: TaskStatus = 'todo') => {
    setTaskToEdit(null);
    setModalInitialStatus(status);
    setIsModalOpen(true);
  };

  const handleOpenEditModal = (task: TaskItem) => {
    setTaskToEdit(task);
    setModalInitialStatus(task.status);
    setIsModalOpen(true);
  };

  const handleCloseModal = () => {
    setIsModalOpen(false);
    setTaskToEdit(null);
  };

  const handleSaveTask = (
    taskData: TaskFormData,
    editId?: string
  ) => {
    if (editId) {
      setTasks((prevTasks) =>
        prevTasks.map((task) =>
          task.id === editId ? { ...task, ...taskData } : task
        )
      );
    } else {
      const newTask: TaskItem = {
        ...taskData,
        id: generateUniqueId(),
        createdAt: getLocalDateString(),
      };
      setTasks((prevTasks) => [newTask, ...prevTasks]);
    }
  };

  // フィルタリング
  const normalizedQuery = searchQuery.trim().toLowerCase();
  const filteredTasks = tasks.filter((task) => {
    const matchesSearch =
      normalizedQuery === '' ||
      task.title.toLowerCase().includes(normalizedQuery) ||
      task.description.toLowerCase().includes(normalizedQuery);
    const matchesPriority =
      priorityFilter === 'all' || task.priority === priorityFilter;

    return matchesSearch && matchesPriority;
  });

  const totalCount = tasks.length;
  const inProgressCount = tasks.filter((t) => t.status === 'in_progress').length;
  const doneCount = tasks.filter((t) => t.status === 'done').length;

  return (
    <div className="kanban-app">
      <header className="app-header">
        <h1 className="header-title">
          <ListTodo size={28} color="#3b82f6" />
          カンバンボード
        </h1>
        <div className="header-stats">
          <span className="stat-badge">
            全タスク: <strong>{totalCount}</strong> 件
          </span>
          <span className="stat-badge">
            <Clock size={14} color="#d97706" />
            作業中: <strong>{inProgressCount}</strong>
          </span>
          <span className="stat-badge">
            <CheckCircle2 size={14} color="#16a34a" />
            完了: <strong>{doneCount}</strong>
          </span>
        </div>
      </header>

      <section className="app-toolbar">
        <div style={{ display: 'flex', alignItems: 'center', gap: '8px', flex: 1, minWidth: '220px' }}>
          <Search size={18} color="#64748b" style={{ flexShrink: 0 }} />
          <input
            type="text"
            className="search-input"
            placeholder="タスクを検索..."
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
          />
        </div>

        <select
          className="priority-filter-select"
          value={priorityFilter}
          onChange={(e) => setPriorityFilter(e.target.value as TaskPriority | 'all')}
        >
          <option value="all">すべての優先度</option>
          <option value="high">優先度: 高</option>
          <option value="medium">優先度: 中</option>
          <option value="low">優先度: 低</option>
        </select>

        <button
          type="button"
          className="add-task-btn"
          onClick={() => handleOpenAddModal('todo')}
        >
          <Plus size={18} />
          新規タスク
        </button>
      </section>

      <main className="kanban-board">
        {columnConfigs.map((col) => {
          const colTasks = filteredTasks.filter((t) => t.status === col.status);
          return (
            <KanbanColumn
              key={col.status}
              status={col.status}
              title={col.title}
              tasks={colTasks}
              onDragStart={handleDragStart}
              onDragOver={handleDragOver}
              onDrop={handleDrop}
              onOpenAddModal={handleOpenAddModal}
              onOpenEditModal={handleOpenEditModal}
              onDeleteTask={handleDeleteTask}
              onMoveTask={handleMoveTask}
            />
          );
        })}
      </main>

      <TaskModal
        isOpen={isModalOpen}
        taskToEdit={taskToEdit}
        initialStatus={modalInitialStatus}
        onClose={handleCloseModal}
        onSave={handleSaveTask}
      />
    </div>
  );
};

export default App;
